css:
@font-face { font-family: PF; src: url(node_modules/@fontsource/playfair-display/files/playfair-display-latin-900-normal.woff2); font-weight: 900; }
@font-face { font-family: PF; src: url(node_modules/@fontsource/playfair-display/files/playfair-display-latin-700-normal.woff2); font-weight: 700; }
@font-face { font-family: SS; src: url(node_modules/@fontsource/source-serif-4/files/source-serif-4-latin-400-normal.woff2); font-weight: 400; }
@font-face { font-family: SS; src: url(node_modules/@fontsource/source-serif-4/files/source-serif-4-latin-700-normal.woff2); font-weight: 700; }
@font-face { font-family: OS; src: url(node_modules/@fontsource/oswald/files/oswald-latin-600-normal.woff2); font-weight: 600; }
.card { background: #F3EEE2; color: #141414; font-family: SS;
  background-image: radial-gradient(rgba(0,0,0,.05) 1px, transparent 1.2px); background-size: 7px 7px; }
.mast { position: absolute; left: 80px; right: 140px; top: 240px; border-top: 10px solid #141414; border-bottom: 3px solid #141414; padding: 14px 0 10px; display: flex; justify-content: space-between; font: 600 34px OS; letter-spacing: 3px; text-transform: uppercase; }
.safe { inset: 340px 140px 440px 80px; justify-content: center; }
h1 { font: 900 124px/0.98 PF; margin: 0; letter-spacing: -2px; }
h2 { font: 900 128px/1.0 PF; margin: 0 0 30px; letter-spacing: -1px; }
p { font: 400 60px/1.28 SS; margin: 34px 0 0; }
p b { font-weight: 700; }
.kick { font: 600 48px OS; letter-spacing: 3px; text-transform: uppercase; color: #B3121B; margin: 0 0 24px; }
.stamp { display: inline-block; align-self: flex-start; font: 600 78px OS; letter-spacing: 6px; padding: 8px 30px; border: 8px solid; transform: rotate(-4deg); margin: 10px 0 34px; }
.false { color: #B3121B; border-color: #B3121B; }
.true { color: #141414; background: #FFD84A; border-color: #141414; }
.rule { border-top: 3px solid #141414; padding-top: 22px; }
.hl { background: #FFD84A; padding: 0 8px; }
.col { display: flex; gap: 34px; margin-top: 30px; }
.col > div { flex: 1; border-top: 6px solid #141414; padding-top: 16px; }
.col .t { font: 600 46px OS; letter-spacing: 2px; text-transform: uppercase; }
.col .n { font: 900 104px/1.05 PF; margin-top: 8px; }
.col .s { font: 400 44px/1.25 SS; margin-top: 10px; }
.src { font: 400 46px/1.3 SS; font-style: italic; color: #4a4a4a; }
.card-1 .safe { justify-content: center; padding-top: 0; }
.card-1 h1 { font-size: 172px; }

.card::before { content: attr(data-x); }
.mast::before { content: 'The Peptide Times'; } .mast::after { content: attr(data-n); }
.big { font: 900 300px/0.9 PF; margin: 0; }

.card::after { content: 'Fact-checked with sources  ·  Education only'; position: absolute; left: 80px; right: 140px; top: 1400px; border-top: 3px solid #141414; padding-top: 14px; font: 600 32px OS; letter-spacing: 2px; text-transform: uppercase; color: #555; }
.card-1 h1 { font-size: 190px; }
